import{_ as n,o as t,c as e,a3 as o}from"./chunks/framework.BlfGB29P.js";const d=JSON.parse('{"title":"Python 语言基础","description":"","frontmatter":{"title":"Python 语言基础"},"headers":[],"relativePath":"py-agent/foundations/python-language/index.md","filePath":"py-agent/foundations/python-language/index.md","lastUpdated":1785242340000}'),i={name:"py-agent/foundations/python-language/index.md"};function l(r,a,h,s,p,u){return t(),e("div",null,[...a[0]||(a[0]=[o('<h1 id="python-语言基础" tabindex="-1">Python 语言基础 <a class="header-anchor" href="#python-语言基础" aria-label="Permalink to &quot;Python 语言基础&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>本分组为没有 Python 经验的读者建立后续 Agent 开发所需的语言基础。它不是 Python 百科，但凡是纳入主线的知识，都会说清概念、语法、核心 API、运行规则和使用边界。</p><h2 id="本分组的作用" tabindex="-1">本分组的作用 <a class="header-anchor" href="#本分组的作用" aria-label="Permalink to &quot;本分组的作用&quot;">​</a></h2><p>快速开始让读者先看到模型调用的结果；本分组则回头补齐读写 Python 代码所需的语言模型。学完后，读者才进入“Python 抽象与组织”，学习作用域、模块、类、异常和资源管理。</p><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><p>完成本分组后，读者应当能够：</p><ol><li>识别 Python 程序中的语句、表达式、缩进代码组和执行顺序。</li><li>用对象和名称绑定解释赋值、相等、身份和修改传播。</li><li>正确使用数字、布尔值、字符串、字节、序列、字典和集合。</li><li>根据数据职责选择容器，并判断何时会出现共享引用、浅复制和深复制问题。</li><li>用条件、模式匹配、循环和函数组织可预测的执行流程。</li><li>理解可迭代对象、迭代器、生成器、推导式和惰性求值之间的关系。</li></ol><h2 id="学习顺序" tabindex="-1">学习顺序 <a class="header-anchor" href="#学习顺序" aria-label="Permalink to &quot;学习顺序&quot;">​</a></h2><h3 id="_1-代码与值" tabindex="-1">1. 代码与值 <a class="header-anchor" href="#_1-代码与值" aria-label="Permalink to &quot;1. 代码与值&quot;">​</a></h3><ol><li><a href="/py-agent/foundations/python-language/program-structure">Python 程序结构</a></li><li><a href="/py-agent/foundations/python-language/execution-objects-names">对象、名称与赋值</a></li><li><a href="/py-agent/foundations/python-language/numbers-arithmetic">数字与算术</a></li><li><a href="/py-agent/foundations/python-language/booleans-comparisons-truthiness">布尔、比较与真值</a></li><li><a href="/py-agent/foundations/python-language/strings-text-processing">字符串与文本处理</a></li><li><a href="/py-agent/foundations/python-language/bytes-encoding">字节与字符编码</a></li></ol><h3 id="_2-容器与对象关系" tabindex="-1">2. 容器与对象关系 <a class="header-anchor" href="#_2-容器与对象关系" aria-label="Permalink to &quot;2. 容器与对象关系&quot;">​</a></h3><ol start="7"><li><a href="/py-agent/foundations/python-language/lists-tuples">序列：列表与元组</a></li><li><a href="/py-agent/foundations/python-language/dictionaries">字典</a></li><li><a href="/py-agent/foundations/python-language/sets">集合</a></li><li><a href="/py-agent/foundations/python-language/mutability-copying">可变对象与复制</a></li></ol><h3 id="_3-执行流与迭代" tabindex="-1">3. 执行流与迭代 <a class="header-anchor" href="#_3-执行流与迭代" aria-label="Permalink to &quot;3. 执行流与迭代&quot;">​</a></h3><ol start="11"><li><a href="/py-agent/foundations/python-language/conditions-pattern-matching">条件与模式匹配</a></li><li><a href="/py-agent/foundations/python-language/loops-iteration">循环与遍历</a></li><li><a href="/py-agent/foundations/python-language/functions">函数</a></li><li><a href="/py-agent/foundations/python-language/iterators-generators">迭代器与生成器</a></li><li><a href="/py-agent/foundations/python-language/comprehensions-generator-expressions">推导式与生成器表达式</a></li></ol><h2 id="内容边界" tabindex="-1">内容边界 <a class="header-anchor" href="#内容边界" aria-label="Permalink to &quot;内容边界&quot;">​</a></h2><p>本分组不展开字节码与 CPython 内部、模块与包、作用域与闭包、装饰器、类、异常体系、类型标注、文件 I/O、Base64、异步编程和 HTTP。这些内容要么属于后续 Python 分组，要么不是 Agent 开发主线的必学基础。</p>',17)])])}const y=n(i,[["render",l]]);export{d as __pageData,y as default};
